#include <iostream>
int main() {
    int price, amount, discount;
    if (!(std::cin >> price >> amount >> discount)) { std::cout << "invalid\n"; return 0; }
    if (price < 0 || price > 1000 || amount < 0 || amount > 1000 || discount < 0 || discount > 100) {
        std::cout << "invalid\n";
        return 0;
    }
    int subtotal = price * amount;
    int saving = subtotal * discount / 100;
    std::cout << subtotal - saving << '\n';
}
